public class Main {
    static int countEven(int n) {
        int count = 0;
        for (int i = 1; i <= n; i++) {
            if (i % 2 == 0) {
                count = count + 1;
            }
        }
        return count;
    }
    public static void main(String[] args) {
        System.out.println(countEven(4));
    }
}

